4830|        if ($bs -gt 0) { [void]$sb.Append('\', $bs); $bs = 0 }
4831|        [void]$sb.Append($ch)
4832|    }
4833|    if ($bs -gt 0) { [void]$sb.Append('\', 2 * $bs) }
