4762|function Get-ClaudeSchemaText {
4763|    param([string]$Path)
4764|    $text = ''
4765|    try { $text = [IO.File]::ReadAllText($Path, $script:Utf8NoBom) } catch { return '' }
4766|    $sb = New-Object System.Text.StringBuilder
4767|    $inStr = $false
4768|    $esc = $false
4769|    foreach ($ch in $text.ToCharArray()) {
4770|        if ($inStr) {
4771|            [void]$sb.Append($ch)
4772|            if ($esc) { $esc = $false } elseif ($ch -eq [char]'\') { $esc = $true } elseif ($ch -eq [char]'"') { $inStr = $false }
4773|            continue
4774|        }
4775|        if ($ch -eq [char]'"') { $inStr = $true; [void]$sb.Append($ch); continue }
4776|        if ([char]::IsWhiteSpace($ch) -or $ch -eq [char]0xFEFF) { continue }
4777|        [void]$sb.Append($ch)
4778|    }
